def solve_tsp(distances: List[List[int]]) -> int:
    def tsp(current_city: int, visited: List[bool], cities: int, cost: int, memo: dict) -> int:
        if cities == 0:
            return cost + distances[current_city][0]

        if (current_city, tuple(visited)) in memo:
            return memo[(current_city, tuple(visited))]

        min_cost = float('inf')
        for next_city in range(cities):
            if not visited[next_city]:
                visited[next_city] = True
                min_cost = min(min_cost, tsp(next_city, visited, cities - 1, cost + distances[current_city][next_city], memo))
                visited[next_city] = False

        memo[(current_city, tuple(visited))] = min_cost
        return min_cost

    n = len(distances)
    visited = [False] * n
    visited[0] = True
    return tsp(0, visited, n - 1, 0, {})

