from itertools import combinations, permutations

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def lcm_multiple(numbers):
    lcm_value = numbers[0]
    for number in numbers[1:]:
        lcm_value = lcm(lcm_value, number)
    return lcm_value

def is_arithmetic_progression(a, b, c):
    numbers = sorted([a, b, c])
    return 2 * numbers[1] == numbers[0] + numbers[2]

def solve_octagon_prob(numbers):
    octagon_vertices = list(combinations(numbers, 3))
    valid_triangles = 0

    for vertices in octagon_vertices:
        for perm in permutations(vertices):
            if (abs(perm[0] - perm[1]) + abs(perm[1] - perm[2]) + abs(perm[2] - perm[0])) % 2 == 0:
                if is_arithmetic_progression(*sorted(perm)):
                    valid_triangles += 1

    total_triangles = len(octagon_vertices)
    from fractions import Fraction
    probability = Fraction(valid_triangles, total_triangles).limit_denominator()
    return probability.numerator + probability.denominator

# Test cases
assert solve_octagon_prob(list(range(9, 17))) == 107
assert solve_octagon_prob([1, 2, 3, 4, 5, 6, 7, 8]) == 107
