import numpy as np

def distance_to_curve(mx: float, my: float) -> float:
    """
    Calculate the minimum distance from a point (mx, my) to the curve g(x) = (x + 1)/(x - 2) for x > 2.
    The result is converted to meters and rounded to two decimal places.
    """
    def g(x: float) -> float:
        return (x + 1) / (x - 2)

    def distance(x: float) -> float:
        return np.sqrt((x - mx) ** 2 + (g(x) - my) ** 2)

    # Use a numerical method to find the minimum distance
    from scipy.optimize import minimize_scalar
    result = minimize_scalar(lambda x: distance(x), bounds=(2.001, 10), method='bounded')

    min_distance = result.fun
    return round(min_distance * 10, 2)

