def maximize_profit_price(price: int, customers: int, decrease_per_10k: int, new_customers_per_10k: int, cost_coeffs: List[float]) -> float:
    def profit(price: int, customers: int, cost_coeffs: List[float]) -> float:
        n = customers
        cost = cost_coeffs[2] + cost_coeffs[1] * n + cost_coeffs[0] * n ** 2
        revenue = price * customers
        return revenue - cost

    def new_customers(price: int, decrease_per_10k: int, new_customers_per_10k: int) -> int:
        return customers + (new_customers_per_10k * (price - price // 10000 * 10000) // decrease_per_10k)

    def new_price(price: int, decrease_per_10k: int) -> int:
        return price - 10000

    price_max = price
    profit_max = profit(price, customers, cost_coeffs)

    while True:
        new_customers_count = new_customers(price, decrease_per_10k, new_customers_per_10k)
        new_price_value = new_price(price, decrease_per_10k)
        new_profit = profit(new_price_value, new_customers_count, cost_coeffs)

        if new_profit > profit_max:
            profit_max = new_profit
            price_max = new_price_value
        else:
            break

    return price_max / 1000.0

