    def distance(p1: Tuple[float, float, float], p2: Tuple[float, float, float]) -> float:
        return ((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2 + (p1[2] - p2[2]) ** 2) ** 0.5

    def line_equation(p1: Tuple[float, float, float], p2: Tuple[float, float, float]) -> Tuple[float, float, float, float]:
        x1, y1, z1 = p1
        x2, y2, z2 = p2
        return (y2 - y1, x1 - x2, 1, x1 * y2 - x2 * y1)

    def distance_to_line(p: Tuple[float, float, float], line: Tuple[float, float, float, float]) -> float:
        A, B, C, D = line
        return abs(A * p[0] + B * p[1] + C * p[2] + D) / ((A ** 2 + B ** 2 + C ** 2) ** 0.5)

    def find_max_sum_distance(A: Tuple[float, float, float], B: Tuple[float, float, float], C: Tuple[float, float, float], D: Tuple[float, float, float]) -> float:
        max_sum = 0
        best_point = None
