    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def calculate_probability(total_tickets: int, chosen_tickets: int) -> float:
    prime_numbers = [i for i in range(1, total_tickets + 1) if is_prime(i)]
    non_prime_numbers = [i for i in range(1, total_tickets + 1) if not is_prime(i)]

    total_combinations = comb(total_tickets, chosen_tickets)

    valid_combinations = 0

    for combo in combinations(prime_numbers, 2):
        remaining_tickets = total_tickets - 2
        remaining_primes = len(prime_numbers) - 2
        remaining_non_primes = len(non_prime_numbers)

        if (2 * sum(combo) % 2 == 0 and (remaining_tickets - remaining_primes) % 2 == 0):
