from typing import Union

def find_min_first_payment(debt: float, target_percentage: float, months: int, decay_ratio: float) -> Union[int, float]:
    """
    Find the minimum first-month payment to pay off a certain percentage of a debt within a given number of months.

    :param debt: Total debt amount.
    :param target_percentage: Target percentage of debt to pay off as a decimal.
    :param months: Number of months to pay off the debt.
    :param decay_ratio: Ratio by which the payment decreases each month.
    :return: Minimum first-month payment as an integer or float.
    """
    if months == 1:
        return round(debt * target_percentage)

    lower_bound = 0
    upper_bound = debt * target_percentage / (1 - decay_ratio)

    while lower_bound + 1 < upper_bound:
        mid = (lower_bound + upper_bound) / 2
        remaining_debt = debt
        for _ in range(months):
            remaining_debt -= mid * (decay_ratio ** _)
            if remaining_debt <= 0:
                break
        if remaining_debt > 0:
            lower_bound = mid
        else:
            upper_bound = mid

    return round(upper_bound)

