from typing import List

def count_grid_ways(numbers: List[int]) -> int:
    from itertools import combinations, permutations

    def valid_grid(grid):
        return (sum(grid[0]) == sum(grid[1]) == sum(grid[2]) and
                len(set([num for row in grid for num in row])) == 6)

    valid_combinations = []
    for comb in combinations(numbers, 6):
        for perm in permutations(comb):
            grid = [list(perm[:3]), list(perm[3:5]), [perm[5]]]
            if valid_grid(grid):
