from math import comb

def calculate_probability_score(questions: int, options_per_question: int, points_for_correct: int, points_for_incorrect: int, target_score: int) -> float:
    if target_score > 4 * questions or target_score < -questions:
        return 0.0

    correct_answers = (target_score - questions * points_for_incorrect) // points_for_correct
    if correct_answers < 0 or correct_answers > questions:
        return 0.0

    incorrect_answers = questions - correct_answers
    probability = comb(questions, correct_answers) * (1/options_per_question)**correct_answers * (1 - 1/options_per_question)**incorrect_answers

