from math import comb, factorial

def is_valid_distribution(slots: int, books: int) -> bool:
    if books > 2 * slots or books < slots:
        return False
    if books % 2 != slots % 2:
        return False
    return True

def count_valid_distributions(slots: int, books: int) -> int:
    if not is_valid_distribution(slots, books):
        return 0

    if books == slots:
        return 1

    if books == 2 * slots:
        return 1

    count = 0
    for i in range(slots - books + 1):
        if books - 2 * i <= slots - 2 * i and (books - 2 * i) % 2 == 0:
            count += comb(slots - i, books - 2 * i) * factorial(books - 2 * i) // (factorial((books - 2 * i) // 2) * factorial((books - 2 * i) // 2))
    return count

def calculate_p_scaled(slots: int, books: int, scale_factor: int) -> float:
    total_ways = comb(slots + books - 1, books)
    valid_ways = 0

    for books_in_one_slot in range(slots + 1):
        if books - books_in_one_slot > 2 * (slots - 1):
            continue
        for books_in_two_slots in range(slots + 1 - books_in_one_slot):
            if books - books_in_one_slot - books_in_two_slots > 2 * (slots - 2 - books_in_one_slot - books_in_two_slots):
                continue
            for books_in_three_slots in range(slots + 1 - books_in_one_slot - books_in_two_slots):
                if books - books_in_one_slot - books_in_two_slots - books_in_three_slots == 2 * (slots - 3 - books_in_one_slot - books_in_two_slots - books_in_three_slots):
                    valid_ways += comb(slots, books_in_one_slot) * comb(slots - books_in_one_slot, books_in_two_slots) * comb(slots - books_in_one_slot - books_in_two_slots, books_in_three_slots)

    valid_ways = count_valid_distributions(slots, books)
    probability = valid_ways / total_ways
    return scale_factor * probability

