from math import sqrt

def min_travel_time(distance_ab: float, distance_to_road: float, desert_speed: float, road_speed: float) -> float:
    try:
        if distance_ab <= 0 or distance_to_road <= 0 or desert_speed <= 0 or road_speed <= 0:
            raise ValueError("All distances and speeds must be positive values.")

        # Calculate the direct distance from A to B
        direct_distance = distance_ab

        # Calculate the distance from A to the road and then to B
        road_distance = sqrt((distance_ab ** 2) + (distance_to_road ** 2))

        # Calculate the time for both routes
        direct_time = direct_distance / desert_speed * 60
        road_time = road_distance / road_speed * 60

        # Return the minimum time
        return min(direct_time, road_time)

    except ValueError as ve:
        return str(ve)

