from typing import Union

def find_min_first_payment(debt: int, target: float, months: int, decay_ratio: float) -> Union[int, float]:
    def future_debt(m: int, months: int) -> float:
        payment = m
        for _ in range(months):
            payment *= decay_ratio
            debt -= payment
        return debt

    low, high = 0, debt
    while low < high:
        mid = (low + high) / 2
        if future_debt(mid, months) > -debt * target:
            high = mid
        else:
            low = mid + 1
    return round(low)

